public class SumNumericCharacters {
    // Brute Force Approach using Regex Split
    public static int sumNumericBruteForce(String s) {
        if (s == null || s.trim().isEmpty()) return 0;

        // Split by all non-digit sequences
        String[] tokens = s.trim().split("\\D+");
        int sum = 0;

        for (String token : tokens) {
            if (!token.isEmpty()) {
                sum += Integer.parseInt(token);
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(sumNumericBruteForce("10a20b30")); // Output: 60
        System.out.println(sumNumericBruteForce("abc123xyz")); // Output: 123
    }
}

