    public static String getDayBruteForce(int year) {
        boolean isLeap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
        int[] daysInMonth = {31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 14};

        String[] days = {"Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"};
        int dayIdx = 0; // Jan 1st is Monday

        for (int m = 0; m < daysInMonth.length; m++) {
            int maxDays = daysInMonth[m];
            int startDay = (m == 0) ? 2 : 1; // skip Jan 1 since dayIdx starts at Jan 1
            for (int d = startDay; d <= maxDays; d++) {
                dayIdx = (dayIdx + 1) % 7;
            }
        }
        return days[dayIdx];
    }
}

