                    max = Math.max(max, currentNum);
                    numberFound = true;
                    currentNum = 0;
                    buildingNum = false;
                }
            }
        }
        // Flush trailing number if string ends with digit
        if (buildingNum) {
            min = Math.min(min, currentNum);
            max = Math.max(max, currentNum);
            numberFound = true;
        }

        if (numberFound) {
            System.out.println("Min Number: " + min);
            System.out.println("Max Number: " + max);
        } else {
            System.out.println("No numbers found in string.");
        }
    }

    public static void main(String[] args) {
        findMinMaxNumbers("abc123xyz45def678ghj9"); // Min: 9, Max: 678
        findMinMaxNumbers("foo007bar0005baz");      // Min: 5, Max: 7
