import java.io.File;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;

public class DirectoryFileCounter {
    public static Map<String, Integer> countFileTypeExtensions(String directoryPath) {
        Map<String, Integer> extensionMap = new HashMap<>();
        extensionMap.put("class", 0);
        extensionMap.put("txt", 0);
        extensionMap.put("obj", 0);
        extensionMap.put("other", 0);

        Path path = Paths.get(directoryPath);
        if (!Files.exists(path)) return extensionMap;

        try (Stream<Path> stream = Files.walk(path)) {
            stream.filter(Files::isRegularFile).forEach(p -> {
                String filename = p.getFileName().toString().toLowerCase();
                if (filename.endsWith(".class")) {
                    extensionMap.put("class", extensionMap.get("class") + 1);
                } else if (filename.endsWith(".txt")) {
                    extensionMap.put("txt", extensionMap.get("txt") + 1);
                } else if (filename.endsWith(".obj") || filename.endsWith(".object")) {
                    extensionMap.put("obj", extensionMap.get("obj") + 1);
                } else {
                    extensionMap.put("other", extensionMap.get("other") + 1);
                }
            });
        } catch (Exception e) {
            System.err.println("Error walking directory: " + e.getMessage());
        }

        return extensionMap;
    }

    public static void main(String[] args) {
        Map<String, Integer> counts = countFileTypeExtensions("./");
        System.out.println(".class files: " + counts.get("class"));
        System.out.println(".txt files:   " + counts.get("txt"));
        System.out.println(".obj files:   " + counts.get("obj"));
    }
}

