import java.util.*;

public class DecodeStringOptimized {
    public static String decodeString(String s) {
        Deque<Integer> countStack = new ArrayDeque<>();
        Deque<StringBuilder> stringStack = new ArrayDeque<>();
        StringBuilder currentStr = new StringBuilder();
        int k = 0;

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);

            if (Character.isDigit(ch)) {
                k = k * 10 + (ch - '0');
            } else if (ch == '[') {
                countStack.push(k);
                stringStack.push(currentStr);
                currentStr = new StringBuilder();
                k = 0;
            } else if (ch == ']') {
                StringBuilder decoded = stringStack.pop();
                int count = countStack.pop();
                for (int c = 0; c < count; c++) {
                    decoded.append(currentStr);
                }
                currentStr = decoded;
            } else if (Character.isLetter(ch)) {
                currentStr.append(ch);
            }
        }

        return currentStr.toString();
    }

    public static void main(String[] args) {
        System.out.println(decodeString("3[a] 2[bc]")); // aabcbc
        System.out.println(decodeString("3[a2[c]]"));   // accaccacc
        System.out.println(decodeString("2[abc]3[cd]ef")); // abcabccdcdcdef
    }
}
